// composePlannerDomain 把领域片段嵌进共享正文。缺哪个片段就留空，不会留下标记。
func composePlannerDomain(spec plannerDomainSpec) string {
	body := strings.NewReplacer(
		domainMarkerPerspective, spec.perspective,
		domainMarkerKeyFacts, spec.keyFacts,
		domainMarkerAcceptance, spec.acceptance,
		domainMarkerFocus, spec.focus,
		domainMarkerTaboos, spec.taboos,
	).Replace(plannerDefaultTmpl)
	// 落库时 normalizePlannerTemplate 会 TrimSpace；这里先对齐，任务快照与种子才逐字相等。
	return strings.TrimSpace(body)
}

// PlannerDomainSeeds 返回内置领域模板的 name → body（完整正文，用于首次落库）。
func PlannerDomainSeeds() map[string]string {
	out := make(map[string]string, len(plannerDomainSpecs))
	for _, spec := range plannerDomainSpecs {
		out[spec.name] = composePlannerDomain(spec)
	}
	return out
}
